#!/bin/bash
# RPD-RECO data-free prologue (the director's go, 2026-11-07, under coverage-5b-audit's run clearance): Codex2's
#   bash $CHECKOUT/nd-unfolding/fd_rpd_reco_prologue_connect.sh "$CHECKOUT" "$DRAFT_POLICY_CONFIG" "$CONFIG_SHA" "$PROLOGUE_RUN" "$MAT_PYTHON"
# at #848's head 4ea4a113, from a fresh clone, on a login node at 0 node-h. Before it, in this connect: the COV2D fence
# (squeue cov2d-* must be empty, else STOP), the clone's HEAD and porcelain, the resolved policy config written from
# this script and checked against its sha256, and the strace probe. MAT_PYTHON is root_6_28's python3, the interpreter
# receipts-rpd/root_tests_login.log measured in the pinned MAT environment. Everything is under the literal root
# /dev/shm/limres-rpd-prologue-20261107 (refused if it exists). The run directory is left for the tar-back connect, and
# a third connect removes the root by its literal path. Launched from a /dev/shm copy of itself ($1), which it deletes.
SELF=$1
S=4ea4a113f72f32465f2a8c4eddd7bbaa2db5683c
CFG_SHA=3992108792db2bc7c26b570531efec2df739a392398c03af366b82eb9190fa4b
MAT_PYTHON=/global/homes/j/josephrb/.conda/envs/root_6_28/bin/python3
finish() { echo "== rpd-prologue rc=$1 $(date -u +%FT%TZ)"; rm -f -- "$SELF"; exit "$1"; }
case "$(hostname)" in login*) ;; *) echo "STOP: not a login node: $(hostname)"; finish 9 ;; esac
[ ! -e /dev/shm/limres-rpd-prologue-20261107 ] || { echo "STOP: /dev/shm/limres-rpd-prologue-20261107 exists"; finish 9; }
echo "node $(hostname) $(date -u +%FT%TZ)"
echo "connect script sha256 $(sha256sum "$SELF" | cut -d' ' -f1)"
echo "== COV2D fence, immediately before (must be empty)"
fence=$(squeue -u josephrb -h -o '%i|%j|%T|%M|%l'); frc=$?
hits=$(printf '%s\n' "$fence" | awk -F'|' '$2 ~ /^cov2d-/')
echo "squeue rc=$frc; cov2d-* rows: [$hits]"
[ "$frc" -eq 0 ] && [ -z "$hits" ] || { echo "STOP: the fence is not clear"; finish 3; }
mkdir /dev/shm/limres-rpd-prologue-20261107 || finish 9
echo "== fresh clone at $S"
git clone --quiet --filter=blob:none --no-checkout https://github.com/josephbaileyy/MINERvA-OmniFold.git   /dev/shm/limres-rpd-prologue-20261107/repo || { echo "STOP: clone failed"; finish 5; }
git -C /dev/shm/limres-rpd-prologue-20261107/repo -c advice.detachedHead=false checkout --quiet "$S" || { echo "STOP: checkout failed"; finish 5; }
head=$(git -C /dev/shm/limres-rpd-prologue-20261107/repo rev-parse HEAD)
porc=$(git -C /dev/shm/limres-rpd-prologue-20261107/repo status --porcelain | wc -l)
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "$S" ] && [ "$porc" -eq 0 ] || { echo "STOP: the clone is not $S clean"; finish 5; }
for f in nd-unfolding/fd_rpd_reco_prologue_connect.sh nd-unfolding/fd_rpd_reco_prologue.py nd-unfolding/fd_rpd_reco.py nd-unfolding/fd_rpd_reco_custody.py nd-unfolding/fd_rpd_inputs.py; do
  echo "blob $(git -C /dev/shm/limres-rpd-prologue-20261107/repo rev-parse "$S:$f") sha256 $(sha256sum "/dev/shm/limres-rpd-prologue-20261107/repo/$f" | cut -d' ' -f1) $f"
done
echo "== the resolved policy config"
printf '%s' '' | base64 -d > /dev/shm/limres-rpd-prologue-20261107/policy-config.json
got=$(sha256sum /dev/shm/limres-rpd-prologue-20261107/policy-config.json | cut -d' ' -f1)
echo "policy config sha256 $got (expected $CFG_SHA)"
[ "$got" = "$CFG_SHA" ] || { echo "STOP: config digest"; finish 5; }
echo "== strace probe"
/usr/bin/strace -f -e trace=open,openat,openat2 -o /dev/shm/limres-rpd-prologue-20261107/strace-probe.txt /bin/true
echo "strace probe rc=$? lines $(wc -l < /dev/shm/limres-rpd-prologue-20261107/strace-probe.txt)"
echo "== the prologue: bash fd_rpd_reco_prologue_connect.sh CHECKOUT CONFIG SHA RUN MAT_PYTHON"
bash /dev/shm/limres-rpd-prologue-20261107/repo/nd-unfolding/fd_rpd_reco_prologue_connect.sh   /dev/shm/limres-rpd-prologue-20261107/repo /dev/shm/limres-rpd-prologue-20261107/policy-config.json "$CFG_SHA"   /dev/shm/limres-rpd-prologue-20261107/run "$MAT_PYTHON"
p=$?
echo "prologue wrapper rc=$p"
echo "== run directory"
find /dev/shm/limres-rpd-prologue-20261107/run -maxdepth 2 -printf '%y %s %P\n' | sort -k3
for f in data-free-trace.json worker.stderr.txt worker.stdout.txt prologue-worker.json; do
  q=/dev/shm/limres-rpd-prologue-20261107/run/$f
  if [ -f "$q" ]; then echo "== FILE $f sha256 $(sha256sum "$q" | cut -d' ' -f1)"; head -c 20000 "$q"; echo; echo "== END $f"; else echo "== ABSENT $f"; fi
done
finish "$p"
